import{_ as a,c as i,o as t,ag as l}from"./chunks/framework.C86mscM5.js";const u=JSON.parse('{"title":"依赖与镜像安全","description":"","frontmatter":{},"headers":[],"relativePath":"devops/security-reliability/dependency-and-image-security.md","filePath":"devops/security-reliability/dependency-and-image-security.md","lastUpdated":1788092044000}'),r={name:"devops/security-reliability/dependency-and-image-security.md"};function o(n,e,d,s,c,p){return t(),i("div",null,e[0]||(e[0]=[l('<h1 id="依赖与镜像安全" tabindex="-1">依赖与镜像安全 <a class="header-anchor" href="#依赖与镜像安全" aria-label="Permalink to &quot;依赖与镜像安全&quot;">​</a></h1><h2 id="源码依赖" tabindex="-1">源码依赖 <a class="header-anchor" href="#源码依赖" aria-label="Permalink to &quot;源码依赖&quot;">​</a></h2><ul><li>提交锁文件并使用严格安装模式，保证 CI 与本地解析结果一致。</li><li>限制包仓库来源，防范依赖混淆；私有包使用受控 Scope 和 Registry。</li><li>审查安装脚本、维护状态、许可证和传递依赖，不只查看下载量。</li><li>使用 Dependabot、Renovate 等持续提出升级，避免积累无法一次消化的大版本差距。</li><li>扫描发现 CVE 后结合实际调用路径、暴露面和修复版本判断风险，记录有期限的例外。</li></ul><h2 id="镜像" tabindex="-1">镜像 <a class="header-anchor" href="#镜像" aria-label="Permalink to &quot;镜像&quot;">​</a></h2><ul><li>选择维护中的最小基础镜像，固定版本或 digest，并定期重建。</li><li>多阶段构建移除编译器、包管理缓存、源码和测试工具。</li><li>使用非 root 用户、只读文件系统和最少 Linux capabilities。</li><li>在 CI 与 Harbor 中扫描镜像，高危可利用漏洞阻止晋级。</li><li>生产只部署完成 SBOM、扫描和签名验证的镜像。</li></ul><h2 id="门禁策略" tabindex="-1">门禁策略 <a class="header-anchor" href="#门禁策略" aria-label="Permalink to &quot;门禁策略&quot;">​</a></h2><p>门禁必须说明扫描器版本、漏洞数据库时间、严重等级、是否存在修复和例外审批。单纯规定“零漏洞”通常会造成忽略告警；更可行的策略是阻止新增且可利用的高危问题，并给存量风险设置所有者和截止时间。</p><h2 id="运行时" tabindex="-1">运行时 <a class="header-anchor" href="#运行时" aria-label="Permalink to &quot;运行时&quot;">​</a></h2><p>构建时无漏洞不代表运行时安全。还需要资源限制、网络策略、Seccomp/AppArmor、异常行为观测和及时补丁。镜像更新后必须重新部署，运行中的旧容器不会自动获得修复。</p>',9)]))}const _=a(r,[["render",o]]);export{u as __pageData,_ as default};
